<?php $snapshot=json_decode($order['supplier_snapshot'],true);$address=$order['address_snapshot']?json_decode($order['address_snapshot'],true):null; ?>
<div class="page-heading"><div><div class="eyebrow"><?= $invoice?'RECEIPT / INVOICE':'PURCHASE DETAILS' ?></div><h1>Order #<?= str_pad($order['id'],5,'0',STR_PAD_LEFT) ?></h1><p><?= e($snapshot['name']) ?> · <?= e($order['created_at']) ?> UTC</p></div><div><?php if($invoice):?><button class="btn btn-primary" data-print>Print receipt</button><?php else:?><a href="/invoice?id=<?= $order['id'] ?>" class="btn btn-outline-secondary">Printable receipt ↗</a><?php endif;?></div></div><div class="two-column"><section class="panel"><h2>Order status</h2><div class="status-pair"><span class="badge <?= $order['mode']==='demo'?'demo-badge':'soft-badge' ?>"><?= e(str_replace('_',' ',$order['payment_status'])) ?><?= $order['mode']==='demo'?' · No real payment':'' ?></span><span class="badge soft-badge"><?= e(str_replace('_',' ',$order['status'])) ?></span></div><p><?= e(ucfirst($order['fulfillment'])) ?> · <?= e($order['instructions']) ?></p><?php if($address&&$order['fulfillment']==='delivery'):?><strong>Delivery address</strong><p><?= e($address['address']) ?><br><?= e($address['city']) ?></p><?php endif;?><?php if(in_array($role,['wholesaler','admin'],true)&&in_array($order['payment_status'],['paid','demo_paid','partially_refunded'],true)):foreach(App\services\Orders::next($order['status'],$order['fulfillment']) as $state):?><form action="/order/status" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $order['id'] ?>"><input type="hidden" name="status" value="<?= $state ?>"><button class="btn btn-primary">Mark <?= e(str_replace('_',' ',$state)) ?> →</button></form><?php endforeach;endif;?></section><section class="panel"><h2>Payment breakdown</h2><?php foreach(['subtotal'=>'Merchandise','delivery'=>'Delivery','tax'=>'Tax','fee'=>'Buyer fee','total'=>'Total'] as $key=>$label):?><div class="total-row"><span><?= $label ?></span><strong><?= money($order[$key]) ?></strong></div><?php endforeach;?><?php if($refund):?><hr><div class="total-row"><span>Refund <?= e($refund['status']) ?></span><strong><?= money($refund['amount']) ?></strong></div><?php endif;?></section></div><div class="table-panel"><table><thead><tr><th>Product snapshot</th><th>Pack</th><th>Quantity</th><th>Pack price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><strong><?= e($i['name']) ?></strong><small><?= e($i['sku']) ?></small></td><td><?= e($i['pack_size'].' '.$i['unit']) ?></td><td><?= $i['quantity'] ?></td><td><?= money($i['price']) ?></td><td><?= money($i['total']) ?></td></tr><?php endforeach;?></tbody></table></div>
<div class="two-column"><section class="panel"><h2>Status history</h2><?php foreach($history as $h):?><div class="history-row"><span class="status-dot"></span><strong><?= e(str_replace('_',' ',$h['status'])) ?></strong><small><?= e($h['created_at']) ?> UTC</small></div><?php endforeach;?></section><?php if($role==='retailer'&&!$invoice):?><section class="panel"><h2>Purchase notes</h2><form method="post" action="/order/notes"><?= csrf() ?><input type="hidden" name="id" value="<?= $order['id'] ?>"><label>Private purchase note<textarea name="notes" maxlength="2000" rows="3"><?= e($order['notes']) ?></textarea></label><button class="btn btn-outline-secondary">Save note</button></form><hr><form method="post" action="/messages/start"><?= csrf() ?><input type="hidden" name="supplier_id" value="<?= $order['supplier_id'] ?>"><input type="hidden" name="order_id" value="<?= $order['id'] ?>"><label>Ask your supplier<textarea name="body" required maxlength="4000" rows="2"></textarea></label><button class="btn btn-primary">Send private message</button></form></section><?php endif;?><?php if($role==='admin'&&!$invoice):?><section class="panel"><h2>Payment operations</h2><p>Cancel and refund the whole supplier order, including its delivery, tax and buyer fee. Other supplier orders remain unchanged. Unshipped inventory is restocked once.</p><?php if((!$refund || $refund['status']==='pending') && in_array($order['payment_status'],['paid','demo_paid','partially_refunded'],true)&&!in_array($order['status'],['shipped','delivered','cancelled'],true)):?><form action="/admin/refund" method="post" data-confirm="Refund this supplier order and restock its inventory?"><?= csrf() ?><input type="hidden" name="id" value="<?= $order['id'] ?>"><button class="btn btn-outline-danger">Cancel & refund supplier order</button></form><?php endif;?><?php if($order['mode']==='stripe'&&$order['status']==='delivered'&&$order['payment_status']==='paid'):?><form action="/admin/payout" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $order['id'] ?>"><button class="btn btn-primary">Send Connect test payout</button></form><?php endif;?></section><?php endif;?></div>
